# Generated by manage.py generate_test_cases.
"""Verify URL widget markup, field-type selection and native form semantics."""

from typing import Any

from bs4 import BeautifulSoup
from django.http import QueryDict

from bloomerp.field_types.builtins.text import URL_FIELD
from bloomerp.field_types.registry import FieldContext
from bloomerp.tests.base import BloomerpWidgetTestCase, WidgetOperation, WidgetScenario
from bloomerp.widgets.url_widget import URLWidget


class TestURLWidget(BloomerpWidgetTestCase[URLWidget]):
    """Cover URL input rendering and raw values without database fixtures."""

    widget_class = URLWidget

    def _render(self, widget: URLWidget) -> str:
        """Render a URL containing quotes with native form attributes."""
        return widget.render(
            "website",
            'https://example.com/?q="quoted"&x=1',
            attrs={
                "id": "id_website",
                "required": True,
                "maxlength": 200,
                "class": "input custom",
                "aria-describedby": "url_help",
            },
        )

    def _validate_markup(self, value: Any) -> bool:
        """Verify escaping, input identity, spacing and a non-submitting view action."""
        markup = BeautifulSoup(value, "html.parser")
        field = markup.select_one('input[type="url"]')
        button = markup.select_one("button[data-open-url]")
        return bool(
            field
            and button
            and len(markup.select("input")) == 1
            and field["name"] == "website"
            and field["id"] == "id_website"
            and field["value"] == 'https://example.com/?q="quoted"&x=1'
            and field.has_attr("required")
            and field["maxlength"] == "200"
            and field["aria-describedby"] == "url_help"
            and "custom" in field["class"]
            and "pr-10!" in field["class"]
            and button["type"] == "button"
            and button.has_attr("disabled")
            and button["aria-label"] == "Open URL in a new tab"
            and button.select_one('i.fa-eye[aria-hidden="true"]')
            and markup.select_one('[bloomerp-component="url-widget"]')
        )

    def _extract(self, widget: URLWidget) -> Any:
        """Extract current submitted values unchanged for URLField validation."""
        return [
            widget.value_from_datadict(
                QueryDict("website=https%3A%2F%2Fnew.example"), {}, "website"
            ),
            widget.value_from_datadict(QueryDict("website="), {}, "website"),
            widget.value_from_datadict({}, {}, "website"),
        ]

    def _validate_extraction(self, value: Any) -> bool:
        """Keep ordinary Django scalar, blank and missing-value semantics."""
        return value == ["https://new.example", "", None]

    def _states(self, widget: URLWidget) -> list[str]:
        """Render empty, disabled and read-only values with normal input attributes."""
        return [
            widget.render("website", None),
            widget.render("website", "https://example.com", {"disabled": True}),
            widget.render("website", "https://example.com", {"readonly": True}),
        ]

    def _validate_states(self, value: Any) -> bool:
        """Preserve blank rendering and read-only/disabled distinctions."""
        fields = [
            BeautifulSoup(html, "html.parser").select_one("input") for html in value
        ]
        return (
            not fields[0].has_attr("value")
            and fields[1].has_attr("disabled")
            and fields[2].has_attr("readonly")
            and not fields[2].has_attr("disabled")
        )

    def _field_type(self, widget: URLWidget) -> bool:
        """Confirm the registered URL field selects this widget and preserves attrs."""
        selected = URL_FIELD.widget_factory(FieldContext(attrs={"id": "custom_url"}))
        return isinstance(selected, URLWidget) and selected.attrs["id"] == "custom_url"

    def _true(self, value: Any) -> bool:
        """Require the registry contract to hold."""
        return value is True

    def get_test_scenarios(self) -> list[WidgetScenario[URLWidget]]:
        """Exercise presentation, form submission and registry integration."""
        return [
            WidgetScenario(
                name="URL field keeps native input semantics",
                operations=[
                    WidgetOperation(
                        name="Safe input and view action",
                        execute=self._render,
                        result_validators=self._validate_markup,
                    ),
                    WidgetOperation(
                        name="Raw submitted values",
                        execute=self._extract,
                        result_validators=self._validate_extraction,
                    ),
                    WidgetOperation(
                        name="Empty and non-editable inputs",
                        execute=self._states,
                        result_validators=self._validate_states,
                    ),
                    WidgetOperation(
                        name="URL field widget registration",
                        execute=self._field_type,
                        result_validators=self._true,
                    ),
                ],
            )
        ]
